/**
 * Copies a rectangular cuboid of blocks from (srcX, srcY, srcZ) to (dstX, dstY, dstZ) with given width/height/depth.
 * @param {number} srcX     - Source X coordinate (top-left corner of the selection)
 * @param {number} srcY     - Source Y coordinate (bottom/top, depending on your coordinate system)
 * @param {number} srcZ     - Source Z coordinate (left-right)
 * @param {number} dstX     - Destination X coordinate (where to put the clone)
 * @param {number} dstY     - Destination Y coordinate
 * @param {number} dstZ     - Destination Z coordinate
 * @param {number} w        - Width (in blocks) of the clone
 * @param {number} h        - Height (in blocks) of the clone
 * @param {number} d        - Depth (in blocks) of the clone
 */
function cloneBlock(srcX, srcY, srcZ, dstX, dstY, dstZ, w, h, d) {
    for (let x = 0; x < w; x++) {
        for (let y = 0; y < h; y++) {
            for (let z = 0; z < d; z++) {
                let srcXi = srcX + x;
                let srcYi = srcY + y;
